fn main(){use std::process::Command;use std::path::PathBuf;let out=PathBuf::from(std::env::var("OUT_DIR").unwrap());let obj=out.join("dg_rhs.o");let ar=out.join("libdg_rhs.a");assert!(Command::new("g++").args(["-O3","-std=c++17","-fopenmp","-fPIC","-c","dg_rhs.cpp","-o"]).arg(&obj).status().unwrap().success());assert!(Command::new("ar").arg("crs").arg(&ar).arg(&obj).status().unwrap().success());println!("cargo:rustc-link-search=native={}",out.display());println!("cargo:rustc-link-lib=dylib=stdc++");println!("cargo:rustc-link-lib=dylib=gomp");println!("cargo:rerun-if-changed=dg_rhs.cpp");}
